export class LazyPromise extends Promise {
    static from(execute) {
        return new LazyPromise((resolve)=>{
            resolve(execute());
        });
    }
    static resolve(value) {
        return new LazyPromise((resolve)=>{
            resolve(value);
        });
    }
    static reject(reason) {
        return new LazyPromise((_, reject)=>{
            reject(reason);
        });
    }
    #execute;
    #promise;
    constructor(execute){
        super((resolve)=>resolve(undefined));
        this.#execute = execute;
    }
    // biome-ignore lint/suspicious/noThenProperty: expected behavior
    then(onFulfilled, onRejected) {
        this.#promise ??= new Promise(this.#execute);
        return this.#promise.then(onFulfilled, onRejected);
    }
    catch(onRejected) {
        this.#promise ??= new Promise(this.#execute);
        return this.#promise.catch(onRejected);
    }
    finally(onFinally) {
        this.#promise ??= new Promise(this.#execute);
        return this.#promise.finally(onFinally);
    }
}
/**
 * Lazily run the `execute` function at most once when awaited.
 */ export function lazy(execute) {
    return LazyPromise.from(execute);
}
